package com.greenlink.controller; import com.greenlink.dto.AuthResponse; import com.greenlink.security.AppUserPrincipal; import com.greenlink.service.AuthService;  import java.util.Map; import org.bson.types.ObjectId; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService service;public AuthController(AuthService s){service=s;} @PostMapping("/register") public ResponseEntity<AuthResponse> register(@RequestBody Map<String,Object> b){return ResponseEntity.status(201).body(service.register((String)b.get("name"),(String)b.get("email"),(String)b.get("password"),(Boolean)b.get("isProvider")));} @PostMapping("/login") public AuthResponse login(@RequestBody Map<String,String> b){return service.login(b.get("email"),b.get("password"));} @GetMapping("/me") public com.greenlink.dto.UserView me(@AuthenticationPrincipal AppUserPrincipal p){return service.me(new ObjectId(p.getId()));}}
